-- Load distribution.DimAgent (dimension, SCD type 2).
-- One stored procedure per destination table (DE Policy v2, 5.3).
-- Generated by `python -m fde render` from models/gold/distribution/DimAgent.yml. Do not edit: change the spec and render again.

CREATE OR ALTER PROCEDURE [distribution].[LoadDimAgent]
    @LoadDate date,
    @LoadStepID varchar(36)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Now datetime2(6) = SYSUTCDATETIME();
    DECLARE @MaxKey bigint = (SELECT COALESCE(MAX([DimAgent_SK]), 0)
                              FROM [distribution].[DimAgent] WHERE [DimAgent_SK] > 0);

    -- Every source row is staged on its business key. Changed
    -- rows are staged again with a NULL key, so the MERGE both
    -- closes the current version and inserts the new one.
    MERGE [distribution].[DimAgent] AS target
    USING (
        SELECT changes.*,
            @MaxKey + ROW_NUMBER() OVER (ORDER BY changes.[Agent_BK]) AS [NewKey]
        FROM (
            SELECT s.[Agent_BK] AS [MergeKey1],
                CAST(s.[Agent_BK] AS varchar(20)) AS [Agent_BK],
                CAST(s.[AgentName] AS varchar(200)) AS [AgentName],
                CAST(s.[BranchCode] AS varchar(10)) AS [BranchCode],
                CAST(s.[IsActive] AS bit) AS [IsActive]
            FROM [stage].[DimAgentSource] AS s
            UNION ALL
            SELECT NULL AS [MergeKey1],
                CAST(s.[Agent_BK] AS varchar(20)) AS [Agent_BK],
                CAST(s.[AgentName] AS varchar(200)) AS [AgentName],
                CAST(s.[BranchCode] AS varchar(10)) AS [BranchCode],
                CAST(s.[IsActive] AS bit) AS [IsActive]
            FROM [stage].[DimAgentSource] AS s
            INNER JOIN [distribution].[DimAgent] AS d
                ON d.[Agent_BK] = s.[Agent_BK] AND d.[IsCurrent] = 1
            WHERE (d.[AgentName] <> s.[AgentName] OR (d.[AgentName] IS NULL AND s.[AgentName] IS NOT NULL) OR (d.[AgentName] IS NOT NULL AND s.[AgentName] IS NULL))
                OR (d.[BranchCode] <> s.[BranchCode] OR (d.[BranchCode] IS NULL AND s.[BranchCode] IS NOT NULL) OR (d.[BranchCode] IS NOT NULL AND s.[BranchCode] IS NULL))
                OR (d.[IsActive] <> s.[IsActive] OR (d.[IsActive] IS NULL AND s.[IsActive] IS NOT NULL) OR (d.[IsActive] IS NOT NULL AND s.[IsActive] IS NULL))
        ) AS changes
    ) AS source
    ON target.[Agent_BK] = source.[MergeKey1]
        AND target.[IsCurrent] = 1
    WHEN MATCHED AND (
        (target.[AgentName] <> source.[AgentName] OR (target.[AgentName] IS NULL AND source.[AgentName] IS NOT NULL) OR (target.[AgentName] IS NOT NULL AND source.[AgentName] IS NULL))
        OR (target.[BranchCode] <> source.[BranchCode] OR (target.[BranchCode] IS NULL AND source.[BranchCode] IS NOT NULL) OR (target.[BranchCode] IS NOT NULL AND source.[BranchCode] IS NULL))
        OR (target.[IsActive] <> source.[IsActive] OR (target.[IsActive] IS NULL AND source.[IsActive] IS NOT NULL) OR (target.[IsActive] IS NOT NULL AND source.[IsActive] IS NULL))
    ) THEN UPDATE SET
        [EndDate] = DATEADD(day, -1, @LoadDate),
        [IsCurrent] = 0,
        [LastUpdateLoadStepID] = @LoadStepID,
        [LastUpdateTimestamp] = @Now
    WHEN NOT MATCHED BY TARGET THEN INSERT (
        [DimAgent_SK],
        [Agent_BK],
        [AgentName],
        [BranchCode],
        [IsActive],
        [StartDate],
        [EndDate],
        [IsCurrent],
        [InsertLoadStepID],
        [InsertTimestamp],
        [LastUpdateLoadStepID],
        [LastUpdateTimestamp]
    ) VALUES (
        source.[NewKey],
        source.[Agent_BK],
        source.[AgentName],
        source.[BranchCode],
        source.[IsActive],
        CASE WHEN source.[MergeKey1] IS NULL THEN @LoadDate ELSE '1900-01-01' END,
        '9999-12-31',
        1,
        @LoadStepID,
        @Now,
        @LoadStepID,
        @Now
    );
END
GO
